<?php require_once __DIR__.'/../includes/auth.php';require_role(['student']);$itemId=(int)($_GET['item_id']??$_POST['item_id']??0);$s=$pdo->prepare("SELECT * FROM item_reports WHERE id=? AND report_type='found' AND status='open' AND user_id<>?");$s->execute([$itemId,current_user()['id']]);$item=$s->fetch();$error='';if(!$item){$pageTitle='Claim unavailable';require __DIR__.'/../includes/header.php';echo '<div class="empty">This item is not available to claim.</div>';require __DIR__.'/../includes/footer.php';exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$details=trim((string)($_POST['claim_details']??''));if(mb_strlen($details)<10||mb_strlen($details)>2000)$error='Please provide 10–2,000 characters describing identifying details.';else{try{$pdo->beginTransaction();$s=$pdo->prepare("INSERT INTO claim_requests(item_report_id,claimant_id,claim_details) VALUES(?,?,?)");$s->execute([$itemId,current_user()['id'],$details]);$claimId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO claim_status_history(claim_id,changed_by,old_status,new_status,notes) VALUES(?,?,?,?,?)")->execute([$claimId,current_user()['id'],null,'pending','Claim submitted']);notify_user($pdo,(int)$item['user_id'],'claim_submitted','A claim was submitted for your found-item report.','claim',$claimId);$pdo->commit();flash('success','Claim submitted. Staff will review the details.');redirect('student/my-claims.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='A claim may already exist for this item, or the request could not be saved.';}}}$pageTitle='Submit claim';require __DIR__.'/../includes/header.php';?><section class="form-wrap"><h1>Claim: <?=e($item['item_name'])?></h1><p>Describe identifying details that are not fully shown in the public listing. Do not post passwords or unnecessary sensitive data.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" class="panel"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="item_id" value="<?=$itemId?>"><label>Ownership details<textarea name="claim_details" rows="6" maxlength="2000" required><?=e($_POST['claim_details']??'')?></textarea></label><button class="btn primary">Submit claim</button></form></section><?php require __DIR__.'/../includes/footer.php';?>
